/**
 * Object storage for exports (02 §2: S3-compatible in production). Development and tests use the
 * local-disk or in-memory implementations. Keys are generated by the server, never taken from a
 * request.
 *
 * Everything the API stores goes through EncryptedStorage, in @synan/db's exported-file format
 * (crypto/files.ts, "EVF1"): a random per-file key wrapped by the active data key (bound to the
 * object key, so a file copied under another key does not open), and the content in authenticated
 * AES-256-GCM frames that cannot be reordered, dropped or truncated. Downloads decrypt as a stream.
 * Objects written by the earlier whole-file envelope (`ev1.` text) are still read, until retention
 * removes them.
 */
import { createReadStream } from "node:fs";
import { mkdir, readFile, rm, stat, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";
import { pipeline, Readable } from "node:stream";
import { decryptFileBuffer, decryptFileStream, encryptFileBuffer, type Cipher } from "@synan/db";

export interface ObjectStorage {
  put(key: string, data: Buffer, contentType: string): Promise<unknown>;
  get(key: string): Promise<Buffer | null>;
  /** A stream of the stored bytes, or null when absent. Optional: `get` is used otherwise. */
  openRead?(key: string): Promise<Readable | null>;
  delete(key: string): Promise<void>;
}

export class LocalDiskStorage implements ObjectStorage {
  private readonly root: string;
  constructor(root: string) {
    this.root = resolve(root);
  }
  private path(key: string) {
    if (!/^[A-Za-z0-9/_.-]+$/.test(key) || key.includes("..")) throw new Error("invalid object key");
    const p = resolve(join(this.root, key));
    if (!p.startsWith(this.root + sep)) throw new Error("invalid object key");
    return p;
  }
  async put(key: string, data: Buffer) {
    const p = this.path(key);
    await mkdir(dirname(p), { recursive: true });
    await writeFile(p, data);
  }
  async get(key: string) {
    try {
      return await readFile(this.path(key));
    } catch {
      return null;
    }
  }
  async openRead(key: string) {
    const p = this.path(key);
    try {
      if (!(await stat(p)).isFile()) return null;
    } catch {
      return null;
    }
    return createReadStream(p);
  }
  async delete(key: string) {
    await rm(this.path(key), { force: true });
  }
}

export class MemoryStorage implements ObjectStorage {
  readonly objects = new Map<string, Buffer>();
  async put(key: string, data: Buffer) {
    this.objects.set(key, data);
  }
  async get(key: string) {
    return this.objects.get(key) ?? null;
  }
  async openRead(key: string) {
    const b = this.objects.get(key);
    return b ? Readable.from([b]) : null;
  }
  async delete(key: string) {
    this.objects.delete(key);
  }
}

const MAGIC = Buffer.from("EVF1", "ascii");

/** Encrypts every object before it reaches the inner store (per-file key, framed AES-GCM). */
export class EncryptedStorage implements ObjectStorage {
  constructor(
    readonly inner: ObjectStorage,
    private readonly cipher: Cipher,
  ) {}
  /** The legacy whole-object envelope (read only). */
  private legacyCtx(key: string) {
    return { table: "object_storage", column: "data", rowId: key };
  }
  /** Stores `data` encrypted; returns the wrapping data key's id (record it) and the stored size. */
  async put(key: string, data: Buffer, contentType: string): Promise<{ keyId: string; sizeBytes: number }> {
    const { bytes, keyId } = await encryptFileBuffer(this.cipher, data, { objectKey: key });
    await this.inner.put(key, bytes, contentType);
    return { keyId, sizeBytes: bytes.length };
  }
  async get(key: string) {
    const raw = await this.inner.get(key);
    if (!raw) return null;
    if (raw.subarray(0, 4).equals(MAGIC)) return decryptFileBuffer(this.cipher, raw, { objectKey: key });
    return Buffer.from(this.cipher.decrypt(raw.toString("utf8"), this.legacyCtx(key)), "base64");
  }
  /** The decrypted content as a stream (constant memory); authentication failures error the stream. */
  async openRead(key: string): Promise<Readable | null> {
    if (!this.inner.openRead) {
      const b = await this.get(key);
      return b ? Readable.from([b]) : null;
    }
    const src = await this.inner.openRead(key);
    if (!src) return null;
    // Peek at the first bytes to tell the framed format from a legacy envelope.
    const it = src[Symbol.asyncIterator]();
    const first = await it.next();
    const head: Buffer = first.done ? Buffer.alloc(0) : Buffer.from(first.value as Buffer);
    const rest = Readable.from((async function* () {
      if (head.length) yield head;
      for (;;) {
        const n = await it.next();
        if (n.done) return;
        yield n.value as Buffer;
      }
    })());
    if (head.subarray(0, 4).equals(MAGIC)) return pipeline(rest, decryptFileStream(this.cipher, { objectKey: key }), () => undefined);
    const chunks: Buffer[] = [];
    for await (const c of rest) chunks.push(c as Buffer);
    return Readable.from([Buffer.from(this.cipher.decrypt(Buffer.concat(chunks).toString("utf8"), this.legacyCtx(key)), "base64")]);
  }
  async delete(key: string) {
    await this.inner.delete(key);
  }
}
